class TestEdgeCases:
    """Verify handling of edge cases and error conditions."""

    def test_concurrent_token_verification(self, auth_manager, valid_token):
        """Should handle concurrent token verification."""
        import concurrent.futures

        def verify_token():
            identity = auth_manager.verify_token(valid_token)
            return identity.agent_id

        with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
            futures = [executor.submit(verify_token) for _ in range(20)]
            results = [f.result() for f in concurrent.futures.as_completed(futures)]

        assert all(result == "agent-001" for result in results)

    def test_token_with_additional_claims(self, auth_manager):
        """Should handle tokens with additional custom claims."""
        additional_claims = {
            "department": "engineering",
            "level": 5,
            "features": ["feature_a", "feature_b"]
        }

        token = auth_manager.generate_token(
            agent_id="agent-001",
            role="worker",
            permissions=["read"],
            **additional_claims
        )

        identity = auth_manager.verify_token(token)
        assert identity.agent_id == "agent-001"

    def test_verify_token_with_none(self, auth_manager):
        """Should raise error for None token."""
        with pytest.raises(AuthenticationError):
            auth_manager.verify_token(None)

    def test_generate_token_with_none_values(self, auth_manager):
        """Should handle None values in token generation."""
        with pytest.raises(ValueError):
            auth_manager.generate_token(
                agent_id=None,
                role="worker",
                permissions=["read"]
            )

    def test_token_replay_attack_detection(self, auth_manager, valid_token):
        """Should detect token replay within expiry window."""
        # Verify same token multiple times
        for _ in range(5):
            identity = auth_manager.verify_token(valid_token)
            assert identity.agent_id == "agent-001"

    def test_very_long_permissions_list(self, auth_manager):
        """Should handle very long permissions list."""
        permissions = [f"perm_{i}" for i in range(1000)]
        token = auth_manager.generate_token(
            agent_id="agent-001",
            role="admin",
            permissions=permissions
        )

        identity = auth_manager.verify_token(token)
        assert len(identity.permissions) == 1000


