class TestIntegration:
    """Verify end-to-end authentication flow."""

    def test_full_authentication_flow(self, auth_manager, valid_agent_data):
        """Should complete full authentication flow successfully."""
        # Generate token
        token = auth_manager.generate_token(
            agent_id=valid_agent_data["agent_id"],
            role=valid_agent_data["role"],
            permissions=valid_agent_data["permissions"]
        )

        # Verify token
        identity = auth_manager.verify_token(token)

        # Use identity
        assert identity.agent_id == valid_agent_data["agent_id"]
        assert identity.role == valid_agent_data["role"]
        assert identity.permissions == valid_agent_data["permissions"]

        # Convert to dict for serialization
        identity_dict = identity.to_dict()
        assert identity_dict["agent_id"] == valid_agent_data["agent_id"]

    def test_multiple_agents_authentication(self, auth_manager):
        """Should handle multiple agents authenticating simultaneously."""
        agents = [
            {"agent_id": "agent-001", "role": "worker", "permissions": ["read"]},
            {"agent_id": "agent-002", "role": "admin", "permissions": ["read", "write", "delete"]},
            {"agent_id": "agent-003", "role": "viewer", "permissions": ["read"]}
        ]

        tokens = []
        for agent in agents:
            token = auth_manager.generate_token(**agent)
            tokens.append(token)

        # Verify all tokens
        for token, agent in zip(tokens, agents):
            identity = auth_manager.verify_token(token)
            assert identity.agent_id == agent["agent_id"]
            assert identity.role == agent["role"]
            assert identity.permissions == agent["permissions"]


