class TestSecurity:
    """Verify security properties of authentication system."""

    def test_token_does_not_expose_secret(self, auth_manager, valid_token):
        """Should not expose secret key in token."""
        assert SECRET_KEY not in valid_token

    def test_token_does_not_expose_algorithm(self, auth_manager, valid_token):
        """Should not expose algorithm in token payload."""
        payload_encoded = valid_token.split('.')[1]
        import base64
        # Add padding if necessary
        payload_encoded += '=' * (4 - len(payload_encoded) % 4)
        payload_decoded = base64.urlsafe_b64decode(payload_encoded).decode('utf-8')
        assert ALGORITHM not in payload_decoded

    def test_jwt_not_vulnerable_to_none_algorithm(self, auth_manager, valid_agent_data):
        """Should reject tokens with 'none' algorithm."""
        # Create token with 'none' algorithm
        import json
        import base64

        header = base64.urlsafe_b64encode(json.dumps({"alg": "none", "typ": "JWT"}).encode()).decode().rstrip('=')
        payload = base64.urlsafe_b64encode(json.dumps({
            "agent_id": valid_agent_data["agent_id"],
            "role": valid_agent_data["role"],
            "permissions": valid_agent_data["permissions"],
            "exp": (datetime.utcnow() + timedelta(minutes=30)).timestamp()
        }).encode()).decode().rstrip('=')

        none_token = f"{header}.{payload}."

        with pytest.raises(AuthenticationError):
            auth_manager.verify_token(none_token)


